        "refs": ["Q0001", "Q0002", "Q0003", "Q0004", "Q0005", "Q0006", "Q0007", "Q0008"],
        "claims": [
          {
            "text": "A recurrent neural network involves feeding the output back as input over a time dimension, creating a feedback loop.",
            "refs": ["Q0001", "Q0002", "Q0003", "Q0004", "Q0005", "Q0006", "Q0007", "Q0008"],
