      "explanation_text": {
        "text": "In a recurrent neural network, the output at one time step is fed back into the network as input for the next time step, forming a loop that processes sequences over time. This is described as a feedback process, analogous to adding ingredients to a soup and adjusting based on the result, and is visualized as a time axis where the same network is applied repeatedly.",
        "refs": ["Q0001", "Q0002", "Q0003", "Q0004", "Q0005", "Q0006", "Q0007", "Q0008"],
        "claims": [
          {
            "text": "The network processes information forward with no loop in a feed‑forward network.",
            "refs": ["Q0001"],
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "related_refs": []
          },
          {
            "text": "RNN creates a feedback loop where output is fed back as input, similar to adjusting a soup recipe based on tasting.",
            "refs": ["Q0002", "Q0003", "Q0008"],
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "related_refs": []
          },
          {
            "text": "The time dimension is represented as a separate axis, indicating that the same network operates across successive time steps.",
            "refs": ["Q0005", "Q0007"],
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "related_refs": []
          },
          {
            "text": "The feedback process repeats: get feedback, provide new input, train, and repeat.",
            "refs": ["Q0006", "Q0008"],
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "continuation",
            "related_refs": []
          }
        ]
      },
